head.script:
scwin.trigger1_onclick = function(e) {
    scwin.init();
};
scwin.init = function() {
    gridView1.setColumnNodeSet("col2", "data:dataList3", "col2", "col1");
    var jsonData2 = [{
        "col1": "하나",
        "col2": "01"
    }, {
        "col1": "둘",
        "col2": "02"
    }, {
        "col1": "셋",
        "col2": "03"
    }];
    dataList2.setJSON(jsonData2);
    var jsonData3 = [{
        col1: "1",
        col2: "ONE"
    }, {
        col1: "2",
        col2: "TWO"
    }, {
        col1: "3",
        col2: "THREE"
    }];
    dataList3.setJSON(jsonData3);
    var jsonData1 = [{
        "col1": "01",
        "col2": "1"
    }, {
        "col1": "02",
        "col2": "2"
    }, {
        "col1": "03",
        "col2": "3"
    }];
    dataList1.setJSON(jsonData1);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_1').innerText == '1 ONE'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_1_1').innerText == '2 TWO'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('title')");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
